SELECT DATE_TRUNC('MONTH', opened_date) AS activity_month, DATE_TRUNC('QUARTER', opened_date) AS quarter_start, COUNT(*) AS event_count, SIZE(COLLECT_SET(status)) AS num_status, SIZE(COLLECT_SET(status)) AS num_status_2, COUNT(*) FILTER (WHERE status = 'OPEN') AS open_rows, SUM(CASE WHEN status = 'FROZEN' THEN balance ELSE 0 END) AS frozen_balance, COUNT_IF(account_type = 'CHECKING') AS checking_events, GROUPING_ID() AS grouping_level FROM accounts GROUP BY GROUPING SETS ((DATE_TRUNC('MONTH', opened_date), DATE_TRUNC('QUARTER', opened_date)), (DATE_TRUNC('MONTH', opened_date)));
